extension ProblemaGES {
    static let todos: [ProblemaGES] = [
        ProblemaGES(
            id: 1,
            nombre: "Enfermedad Renal Crónica Etapa 4 y 5",
            categoria: .renalUrologico,
            nivelIngreso: .secundaria,
            descripcion: "Enfermedad renal crónica en etapas avanzadas (etapa 4: VFG 15-29 mL/min y etapa 5: VFG < 15 mL/min). Incluye manejo conservador, preparación para terapia de sustitución renal, diálisis y trasplante.",
            poblacionObjetivo: "Todas las personas.",
            sospechaDiagnostica: "Paciente con VFG < 30 mL/min/1.73m², elevación persistente de creatinina, síntomas urémicos (náuseas, prurito, fatiga extrema, edema refractario), anemia renal.",
            confirmacionDiagnostica: "Creatinina sérica, clearance de creatinina, ecografía renal, biopsia renal cuando corresponda. VFG 15-29 mL/min confirma etapa 4, VFG < 15 mL/min confirma etapa 5.",
            garantiaOportunidad: "Hemodiálisis: inicio en 7 días desde la indicación médica. Acceso vascular para hemodiálisis: habilitación en 90 días desde la indicación médica. Peritoneodiálisis: inicio en 21 días desde la indicación médica. Estudio pre-trasplante: completar en 10 meses desde la indicación del especialista. Tratamiento inmunosupresor: en donante cadáver desde el trasplante; en donante vivo desde 48 horas antes del trasplante.",
            tratamiento: "Etapa 4: manejo conservador con nefroprotección (IECA/ARA II, iSGLT2), control de factores de riesgo, preparación para terapia de sustitución. En menores de 15 años con retardo de crecimiento: diagnóstico y tratamiento con hormona del crecimiento. Etapa 5: peritoneodiálisis como primera línea de tratamiento; hemodiálisis como alternativa cuando no es posible la peritoneodiálisis. Trasplante renal (donante vivo, vivo cruzado o fallecido) según criterios NTMA, con estudio pre-trasplante completo. Terapia de desensibilización para pacientes hipersensibilizados según criterios NTMA.",
            seguimiento: "En diálisis: controles nefrológicos periódicos con laboratorio mensual (BUN, creatinina, electrolitos, hemograma). Post-trasplante: seguimiento especializado con drogas inmunosupresoras, profilaxis y tratamiento de citomegalovirus según indicación médica, y terapia de rechazo según indicación médica.",
            archivoGuiaSIGGES: "01_-_Enfermedad_Renal_Etapa_4_y_5_V.28.0.pdf",
            flujogramaDerivacion: "FlujogramaPS1"
        ),
        ProblemaGES(
            id: 2,
            nombre: "Cardiopatías Congénitas Operables",
            categoria: .cardiovascular,
            nivelIngreso: .derivaSecundaria,
            descripcion: "Malformaciones estructurales del corazón presentes desde el nacimiento que son susceptibles de corrección quirúrgica.",
            poblacionObjetivo: "Menores de 15 años con cardiopatía congénita operable. También personas adultas con intervención quirúrgica cardíaca realizada antes de los 15 años (acceso a reintervención) y gestantes desde las 20 semanas de gestación (diagnóstico prenatal).",
            sospechaDiagnostica: "Soplo cardíaco patológico, cianosis, dificultad respiratoria, falla de medro, saturación de oxígeno disminuida, taquicardia inexplicada.",
            confirmacionDiagnostica: "Ecocardiograma Doppler color. En casos complejos: estudio hemodinámico, cateterismo cardíaco, angioTAC o resonancia magnética cardíaca.",
            garantiaOportunidad: "Diagnóstico prenatal: confirmación en 30 días desde la sospecha (≥20 semanas de gestación). Diagnóstico postnatal: 48 horas (0–7 días de vida), 21 días (8 días–menor a 2 años) o 180 días (2–15 años) desde la sospecha. Tratamiento CCO Grave: hospitalización en 48 horas desde la estabilización del paciente. Tratamiento CCO Otras: cirugía o procedimiento según indicación médica. Seguimiento post-cirugía: primer control dentro de 1 año desde el alta quirúrgica.",
            tratamiento: "Corrección quirúrgica de la cardiopatía (cierre de CIA, CIV, corrección de tetralogía de Fallot, etc.). Manejo médico preoperatorio. Reintervenciones según indicación médica. Recambio de marcapasos, generador o electrodo según indicación médica.",
            seguimiento: "Control cardiológico periódico post cirugía. Ecocardiograma de seguimiento. Profilaxis de endocarditis según indicación.",
            archivoGuiaSIGGES: "02_-_Cardiopatías_Congénitas_Operables_Menor_15_Añ.pdf"
        ),
        ProblemaGES(
            id: 3,
            nombre: "Cáncer Cervicouterino",
            categoria: .oncologico,
            nivelIngreso: .derivaSecundaria,
            descripcion: "Neoplasia maligna del cuello uterino en etapas pre-invasora e invasora. Incluye diagnóstico, etapificación, tratamiento y seguimiento.",
            poblacionObjetivo: "Personas de 15 años y más.",
            sospechaDiagnostica: "PAP alterado (lesión intraepitelial o carcinoma) en beneficiarios de 25 a 65 años (tamizaje cada 3 años). Genotipificación VPH de alto riesgo oncogénico positiva por PCR en personas de 35 a 45 años (tamizaje cada 5 años, incorporado en DS N°29/2025). Sospecha clínica: sangrado genital anormal, sinusorragia, flujo vaginal persistente.",
            confirmacionDiagnostica: "Colposcopía con biopsia dirigida e Informe de Proceso Diagnóstico (IPD). Pre-invasor: bajo grado (NIE I-II) o alto grado (NIE III/carcinoma in situ). Invasor: confirmación histológica de carcinoma cervicouterino. Etapificación del invasor con examen físico, TAC o resonancia magnética pélvica y abdominal según indicación.",
            garantiaOportunidad: "Tamizaje PAP: resultado en 30 días desde la realización del examen (beneficiarios 25–65 años). Confirmación diagnóstica: en 40 días desde la sospecha. Etapificación (invasor): en 20 días desde la confirmación. Tratamiento pre-invasor bajo grado: en 180 días desde la indicación médica. Tratamiento pre-invasor alto grado: en 30 días desde la confirmación diagnóstica. Tratamiento invasor: en 20 días desde la etapificación. Tratamientos adyuvantes (quimioterapia, radioterapia/braquiterapia, cirugía): en 20 días desde la indicación médica. Seguimiento: primer control en 90 días desde la indicación médica.",
            tratamiento: "Pre-invasor bajo grado: conducta expectante o tratamiento ante progresión. Pre-invasor alto grado: conización (LEEP o cono frío) o histerectomía según caso. Invasor: histerectomía radical, radioterapia, quimioterapia o combinaciones según etapa. Tratamientos adyuvantes: quimioterapia (cisplatino), radioterapia externa, braquiterapia y cirugía adyuvante según indicación médica.",
            seguimiento: "Pre-invasor: controles en Patología Cervical u Oncología con PAP y colposcopía. Invasor: controles en Oncología con examen clínico, PAP e imágenes según protocolo. Primer control garantizado dentro de 90 días desde la indicación médica.",
            archivoGuiaSIGGES: "03_-_Cáncer_Cérvicouterino_v.24.0.pdf"
        ),
        ProblemaGES(
            id: 4,
            nombre: "Alivio del Dolor y Cuidados Paliativos por Cáncer Avanzado",
            categoria: .oncologico,
            nivelIngreso: .secundaria,
            descripcion: "Asistencia activa y seguimiento integral a la persona con cáncer, por un equipo interdisciplinario. El objetivo es asegurar la máxima calidad de vida posible, independiente del estadio clínico, ya sea en cáncer progresivo o no progresivo, mediante el alivio y prevención de síntomas y del sufrimiento asociado a la enfermedad oncológica.",
            poblacionObjetivo: "Todo beneficiario con diagnóstico de cáncer, independiente de su edad y estadio clínico, que requiera asistencia o manejo del dolor y síntomas asociados. El tratamiento puede ser concomitante con el tratamiento del cáncer de origen.",
            sospechaDiagnostica: "Paciente con diagnóstico de cáncer de cualquier origen, en cualquier etapa, que requiera asistencia o manejo del dolor y síntomas asociados. La evaluación puede realizarse por telemedicina.",
            confirmacionDiagnostica: "El médico del equipo oncológico confirma la necesidad de inicio del tratamiento y emite el Informe de Proceso Diagnóstico, derivando a la Unidad de Cuidados Paliativos. Si el paciente viene del extrasistema, debe pasar primero por APS, que lo deriva al especialista mediante Solicitud de Interconsulta.",
            garantiaOportunidad: "El tratamiento se inicia dentro de 5 días desde la confirmación diagnóstica.",
            tratamiento: "Tratamiento integral y cuidados paliativos para cáncer progresivo, o tratamiento integral por alivio del dolor para cáncer no progresivo. El paciente permanece en la Unidad de Cuidados Paliativos mientras lo requiera.",
            seguimiento: "El caso GES permanece abierto de forma indefinida. No aplica cierre por término de tratamiento. El caso solo se cierra por causales atribuibles al usuario.",
            archivoGuiaSIGGES: "04 Alivio del Dolor y Cuidados Paliativos Instructivo GES v2.0.pdf"
        ),
        ProblemaGES(
            id: 5,
            nombre: "Infarto Agudo del Miocardio",
            categoria: .cardiovascular,
            nivelIngreso: .urgencias,
            descripcion: "El IAM forma parte del síndrome coronario agudo, que agrupa cuadros de dolor torácico isquémico clasificados según variables electrocardiográficas y bioquímicas, desde la angina inestable hasta el IAM con supradesnivel del segmento ST y la muerte súbita. Su origen es la erosión o ruptura de una placa ateroesclerótica que forma un trombo intracoronario.",
            poblacionObjetivo: "Todo beneficiario con dolor torácico no traumático o síntomas de IAM tiene acceso a confirmación diagnóstica. Con diagnóstico confirmado, accede a tratamiento médico y prevención secundaria. Quienes hayan tenido bypass coronario o angioplastia percutánea acceden a prevención secundaria, aunque no hayan tenido un infarto previo.",
            sospechaDiagnostica: "Dolor torácico no traumático, con o sin antecedentes de infarto previo. La sospecha puede presentarse en consulta de urgencia, durante una hospitalización por otro problema de salud, o en control post-bypass o post-angioplastia.",
            confirmacionDiagnostica: "Electrocardiograma realizado en la unidad de urgencia, que puede ser informado por telemedicina. El médico de urgencia confirma o descarta el IAM y lo registra en SIGGES.",
            garantiaOportunidad: "Con sospecha: ECG dentro de 30 minutos desde la atención médica de urgencia. Con confirmación y supradesnivel ST: trombolisis dentro de 30 minutos desde la confirmación con ECG, según indicación médica. Primer control de prevención secundaria dentro de 30 días desde el alta por tratamiento médico de IAM, bypass coronario o angioplastia coronaria percutánea.",
            tratamiento: "Con supradesnivel ST confirmado, el médico puede indicar trombolisis. Todos los casos confirmados requieren hospitalización para tratamiento médico. El bypass y la angioplastia de rescate no están cubiertos por el GES. Al alta, se indica seguimiento por prevención secundaria.",
            seguimiento: "Primer control de prevención secundaria dentro de 30 días desde el alta, en cardiología, medicina interna o APS según la red local. Los controles son mensuales. Si durante el seguimiento se confirma un nuevo infarto, se abre un caso GES nuevo.",
            archivoGuiaSIGGES: "5 Infarto Agudo al Miocardio v4.1.pdf"
        ),
        ProblemaGES(
            id: 6,
            nombre: "Diabetes Mellitus Tipo 1",
            categoria: .endocrinoMetabolico,
            nivelIngreso: .cualquierNivel,
            descripcion: "Enfermedad autoinmune con destrucción de células beta pancreáticas y déficit absoluto de insulina.",
            poblacionObjetivo: "Todas las personas.",
            sospechaDiagnostica: "Polidipsia, poliuria, polifagia, baja de peso inexplicada, cetoacidosis diabética. Debut frecuente en niños y adolescentes.",
            confirmacionDiagnostica: "Glicemia en ayunas ≥ 126 mg/dL o glicemia casual ≥ 200 mg/dL con síntomas. Péptido C bajo, anticuerpos anti-GAD, anti-IA2.",
            garantiaOportunidad: "Diagnóstico: consulta con médico especialista en 7 días desde la sospecha por exámenes alterados. Con descompensación: glicemia en Servicio Médico de Urgencia dentro de 30 minutos desde la atención médica. Tratamiento: inicio en 24 horas desde la confirmación diagnóstica.",
            tratamiento: "Insulinoterapia intensificada (basal-bolo o bomba de insulina). Sensor de monitoreo continuo de glicemia (MCG) garantizado GES para menores de 18 años y personas gestantes. Automonitoreo de glicemia en el resto de la población. Educación en conteo de carbohidratos.",
            seguimiento: "Control cada 3 meses con HbA1c. Monitoreo continuo con MCG en menores de 18 años y embarazadas. Screening anual de complicaciones: fondo de ojo, microalbuminuria, perfil lipídico, función renal.",
            archivoGuiaSIGGES: "06_-_Diabetes_Mellitus_1_v.20.0.pdf"
        ),
        ProblemaGES(
            id: 7,
            nombre: "Diabetes Mellitus Tipo 2",
            categoria: .endocrinoMetabolico,
            nivelIngreso: .primaria,
            descripcion: "Enfermedad metabólica crónica con resistencia a insulina y déficit relativo de secreción. Principal causa de morbimortalidad cardiovascular.",
            poblacionObjetivo: "Personas de 15 años y más.",
            sospechaDiagnostica: "Glicemia en ayunas ≥ 100 mg/dL, factores de riesgo (obesidad, antecedentes familiares, síndrome metabólico), polidipsia, poliuria.",
            confirmacionDiagnostica: "Glicemia en ayunas ≥ 126 mg/dL en 2 ocasiones, PTGO ≥ 200 mg/dL a las 2 horas, o HbA1c ≥ 6.5%.",
            garantiaOportunidad: "Diagnóstico: confirmación en 30 días desde la primera consulta con glicemia elevada. Tratamiento: inicio en 24 horas desde la confirmación diagnóstica. Atención por especialista (oftalmología, endocrinología o diabetes): dentro de 60 días desde la derivación, según indicación médica. Primer tamizaje de retinopatía diabética: dentro de 12 meses desde la indicación del equipo tratante.",
            tratamiento: "Cambios en estilo de vida, metformina como primera línea. Asociar iSGLT2 (garantía GES para pacientes con DM2 y enfermedad renal crónica etapa 3 o 4 o insuficiencia cardíaca estadio C), iDPP4, sulfonilureas o insulina según HbA1c y comorbilidades. Tratamiento de pie diabético incluido en la garantía.",
            seguimiento: "Control cada 3-4 meses con HbA1c. Tamizaje de retinopatía diabética garantizado GES (primer tamizaje dentro de 12 meses; seguimiento periódico posterior). Screening anual de complicaciones microvasculares y macrovasculares. Examen de pie diabético.",
            archivoGuiaSIGGES: "07_-_Diabetes_Mellitus_2_v16.0.pdf"
        ),
        ProblemaGES(
            id: 8,
            nombre: "Cáncer de Mama en Personas de 15 Años y Más",
            categoria: .oncologico,
            nivelIngreso: .derivaSecundaria,
            descripcion: "Crecimiento anormal y desordenado de células del epitelio de los conductos o lobulillos mamarios, con capacidad de diseminarse a cualquier sitio del organismo.",
            poblacionObjetivo: "Todo beneficiario de 15 años y más con sospecha accede a confirmación diagnóstica. Con diagnóstico confirmado, accede a tratamiento y seguimiento. Estando en tratamiento, accede a continuarlo. Con recidiva, accede a nueva confirmación diagnóstica, tratamiento y seguimiento.",
            sospechaDiagnostica: "APS detecta la sospecha y deriva al especialista (ginecólogo o gineco-oncólogo) mediante Solicitud de Interconsulta, abriendo el caso GES en etapa de sospecha. La consulta se realiza en la Unidad de Patología Mamaria del nivel secundario.",
            confirmacionDiagnostica: "El especialista evalúa al paciente e indica los exámenes correspondientes. La confirmación puede realizarse mediante evaluación clínica a nivel de especialidad o mediante biopsia estereotáxica. El médico emite el Informe de Proceso Diagnóstico (IPD) para confirmar o descartar el diagnóstico.",
            garantiaOportunidad: "Diagnóstico: dentro de 45 días desde la sospecha con resultado de mamografía; si hay evidencia clínica de cáncer, el plazo es igualmente de 45 días sin exigir mamografía. Etapificación: dentro de 45 días desde la confirmación diagnóstica. Tratamiento primario: inicio dentro de 30 días desde la etapificación. Tratamientos adyuvantes: inicio dentro de 20 días desde la indicación médica. Seguimiento: primer control dentro de 90 días desde la indicación médica.",
            tratamiento: "El caso se presenta al comité oncológico para definir la conducta terapéutica. Las alternativas de tratamiento primario son cirugía, radioterapia, quimioterapia u hormonoterapia. Puede indicarse reconstitución mamaria durante o posterior al tratamiento. El GES también garantiza atención psiquiátrica e intervenciones psicosociales como parte de la atención integral. Si el paciente está fuera del alcance terapéutico, se deriva al PS N°4 de Alivio del Dolor y Cuidados Paliativos.",
            seguimiento: "El primer control se realiza dentro de 90 días desde la indicación médica. Los controles pueden realizarse de forma presencial o por telemedicina. Si durante el seguimiento se detecta una recidiva, el caso se cierra y se abre un nuevo caso GES.",
            archivoGuiaSIGGES: "08_-_Cáncer_de_Mamas_15_Años_y_Más_v14.0.pdf"
        ),
        ProblemaGES(
            id: 9,
            nombre: "Disrafias Espinales",
            categoria: .neurologico,
            nivelIngreso: .secundaria,
            descripcion: "Grupo de patologías caracterizadas por una anomalía en el desarrollo del tubo neural. Se clasifican en disrafias abiertas y cerradas. En las abiertas, las estructuras nerviosas y meníngeas están comunicadas con el medio externo, lo que hace urgente su corrección quirúrgica.",
            poblacionObjetivo: "Todo beneficiario nacido a contar del 1° de julio de 2005: con sospecha tendrá acceso a confirmación diagnóstica; con confirmación diagnóstica tendrá acceso a tratamiento, incluidas reintervenciones; con tratamiento tendrá acceso a rehabilitación. Todo beneficiario independiente de la fecha de nacimiento: con confirmación diagnóstica de disrafia espinal oculta y médula anclada o meningitis a repetición tendrá acceso a tratamiento, incluidas reintervenciones; con tratamiento de disrafia espinal abierta tendrá acceso a rehabilitación según indicación médica; menor de 65 años con disrafia espinal abierta tendrá acceso a ayudas técnicas y atención de rehabilitación para uso de ayudas técnicas, según indicación médica.",
            sospechaDiagnostica: "La sospecha puede surgir en forma prenatal (ecografía obstétrica) o postnatal (controles de recién nacido o niño sano). El médico que detecta signos o síntomas compatibles emite una Solicitud de Interconsulta a Neurología Infantil o Neurocirugía Infantil, lo que abre el caso GES en sospecha. La consulta con el especialista puede realizarse por telemedicina.",
            confirmacionDiagnostica: "El neurocirujano infantil evalúa al paciente y realiza la confirmación diagnóstica, distinguiendo entre disrafia abierta y disrafia cerrada. Emite el Informe de Proceso Diagnóstico (IPD) para confirmar o descartar el problema de salud, lo que activa la garantía de tratamiento.",
            garantiaOportunidad: "Diagnóstico — Disrafia abierta: evaluación por neurocirujano dentro de las primeras 12 horas desde el nacimiento. Disrafia cerrada: consulta con neurocirujano dentro de 90 días desde la sospecha. Tratamiento — Disrafia abierta: cirugía dentro de 72 horas desde el nacimiento; válvula derivativa dentro de 90 días desde la indicación médica; control con neurocirujano dentro de 15 días desde el alta hospitalaria. Disrafia cerrada: cirugía dentro de 60 días desde la indicación médica; control con neurocirujano dentro de 15 días desde el alta hospitalaria. Seguimiento — Disrafia abierta: inicio de rehabilitación dentro de 30 días desde la indicación médica.",
            tratamiento: "En disrafia abierta se realiza intervención quirúrgica integral y, si el paciente lo requiere, instalación de válvula derivativa. En disrafia cerrada se realiza intervención quirúrgica integral. Tras el alta, el médico indica control postquirúrgico con neurocirujano. Las reintervenciones están incluidas en la garantía.",
            seguimiento: "En disrafia abierta, la rehabilitación se inicia dentro de 30 días desde la indicación médica, con prestaciones específicas según edad (0 a <19 meses, 19 meses a <3 años, 3 a <5 años, 5 a <16 años). Incluye ayudas técnicas y atención de rehabilitación para su uso en menores de 65 años, también dentro de los plazos garantizados. El seguimiento se coordina a través de neurología o neurocirugía infantil.",
            archivoGuiaSIGGES: "09_-_Disrafias_Espinales_v26.0.pdf"
        ),
        ProblemaGES(
            id: 10,
            nombre: "Tratamiento Quirúrgico de Escoliosis en Menores de 25 Años",
            categoria: .musculoesqueletico,
            nivelIngreso: .secundaria,
            descripcion: "Deformidad estructural permanente de la columna vertebral en el plano frontal, asociada a componentes rotacionales simultáneos. Es una enfermedad evolutiva que se agrava con el crecimiento y, en la mayoría de los casos, se estabiliza al término de la madurez ósea.",
            poblacionObjetivo: "Todo beneficiario menor de 25 años con confirmación diagnóstica e indicación de tratamiento quirúrgico de escoliosis, siempre que cumpla los criterios de inclusión definidos en la Norma Técnica correspondiente.",
            sospechaDiagnostica: "La sospecha diagnóstica no está garantizada en este GES. El paciente habitualmente llega al especialista traumatólogo desde un tratamiento ortopédico previo que no mostró mejoría o que se agravó. Si el paciente proviene del extrasistema, debe acceder primero a APS para ser derivado al especialista.",
            confirmacionDiagnostica: "El especialista traumatólogo evalúa al paciente, verifica que cumple los criterios de inclusión de la Norma Técnica y determina la necesidad de tratamiento quirúrgico. Al confirmar, emite el Informe de Proceso Diagnóstico (IPD) e inicia el caso GES.",
            garantiaOportunidad: "Tratamiento quirúrgico: debe realizarse dentro de 270 días desde la confirmación diagnóstica. Primer control post-quirúrgico: dentro de 10 días desde el alta hospitalaria.",
            tratamiento: "Intervención quirúrgica integral de escoliosis, que puede corresponder a tipo idiopática, neuromuscular o asociada a mielomeningocele. El especialista deriva al paciente al hospital de referencia para la cirugía. Tras el alta, indica control postquirúrgico con traumatología o neurocirugía.",
            seguimiento: "El primer control post-quirúrgico se realiza dentro de 10 días desde el alta hospitalaria, con traumatología o neurocirugía según corresponda. La consulta puede realizarse por telemedicina.",
            archivoGuiaSIGGES: "10  Escoliosis v2.2.pdf"
        ),
        ProblemaGES(
            id: 11,
            nombre: "Tratamiento Quirúrgico de Cataratas",
            categoria: .oftalmologico,
            nivelIngreso: .derivaSecundaria,
            descripcion: "Opacidad del cristalino que disminuye o perturba la visión. Accede a tratamiento quirúrgico quien tenga agudeza visual ≤ 0,3 con corrección óptica en el mejor ojo.",
            poblacionObjetivo: "Todas las personas.",
            sospechaDiagnostica: "Disminución progresiva de agudeza visual, visión borrosa, deslumbramiento, dificultad para leer o conducir.",
            confirmacionDiagnostica: "Consulta con oftalmólogo: biomicroscopía (lámpara de hendidura). Ecobiometría con cálculo de lente intraocular y ecotomografía ocular si se requiere. Criterio de inclusión: agudeza visual ≤ 0,3 con corrección óptica en el mejor ojo.",
            garantiaOportunidad: "Sospecha → diagnóstico: confirmación en 180 días (ambos ojos incluidos). Diagnóstico → tratamiento: con AV ≤ 0,1 en el mejor ojo, cirugía en 90 días desde confirmación; con AV ≤ 0,3, cirugía en 180 días desde confirmación. En caso bilateral: segundo ojo dentro de 180 días desde la intervención del primer ojo.",
            tratamiento: "Facoemulsificación con implante de lente intraocular. Cirugía ambulatoria con anestesia local.",
            seguimiento: "Control post-quirúrgico incluido en la prestación: primer control a las 24 horas, segundo a los 7 días, tercer control a los 30 días, con alta y cierre de caso GES. Estos controles no tienen plazo garantizado.",
            archivoGuiaSIGGES: "11 Cataratas v1.1.pdf"
        ),
        ProblemaGES(
            id: 12,
            nombre: "Endoprótesis Total de Cadera en Personas de 65 Años y Más",
            categoria: .musculoesqueletico,
            nivelIngreso: .secundaria,
            descripcion: "Enfermedad degenerativa articular, primaria o secundaria, caracterizada por un daño en el cartílago que condiciona pérdida de la función de la articulación de la cadera. Acceden a la garantía personas de 65 años y más con confirmación diagnóstica de artrosis de cadera con limitación funcional severa que requieran endoprótesis total.",
            poblacionObjetivo: "Personas de 65 años y más.",
            sospechaDiagnostica: "Dolor crónico de cadera con limitación funcional severa, cojera, dificultad para caminar y realizar actividades de la vida diaria.",
            confirmacionDiagnostica: "El médico especialista traumatólogo evalúa al paciente y, si confirma que requiere endoprótesis total de cadera, emite el Informe de Proceso Diagnóstico (IPD), lo que abre el caso GES en etapa de confirmación.",
