        ProblemaGES(
            id: 18,
            nombre: "Síndrome de Inmunodeficiencia Adquirida VIH/SIDA",
            categoria: .infeccioso,
            nivelIngreso: .ambos,
            descripcion: "Infección por VIH. Incluye diagnóstico, tratamiento antirretroviral, manejo de infecciones oportunistas y seguimiento.",
            poblacionObjetivo: "Todo beneficiario. Con sospecha o por solicitud del usuario accede a diagnóstico. Las personas gestantes acceden a diagnóstico durante el control prenatal y en preparto si se desconoce su serología. Con confirmación o indicación médica, accede a exámenes y tratamiento antirretroviral. Persona gestante VIH (+) o con serología reactiva, y su recién nacido, acceden a protocolo de prevención de transmisión vertical.",
            sospechaDiagnostica: "Conductas de riesgo, infecciones oportunistas, síndrome retroviral agudo, adenopatías generalizadas, baja de peso, diarrea crónica.",
            confirmacionDiagnostica: "Test de ELISA para VIH reactivo confirmado con segundo ELISA o Western Blot. Carga viral VIH, recuento de CD4.",
            garantiaOportunidad: "Diagnóstico: dentro de 45 días desde sospecha o solicitud del usuario. Consulta médica: dentro de 45 días desde la confirmación. Tratamiento: inicio dentro de 7 días desde la indicación médica. Persona gestante VIH (+): TAR dentro de 7 días desde indicación. Tratamiento parto: profilaxis antirretroviral desde el inicio del trabajo de parto vaginal o 4 horas antes de la cesárea programada. Terapia puerperio VIH (+): medicamentos para interrupción de lactancia dentro de 6 horas del nacimiento. Recién nacido de gestante VIH (+): profilaxis antirretroviral dentro de 4 horas desde el nacimiento.",
            tratamiento: "Terapia antirretroviral (TAR) combinada: 2 INTR + 1 inhibidor de integrasa (dolutegravir). Profilaxis de infecciones oportunistas según CD4.",
            seguimiento: "Carga viral y CD4 al inicio, a los 3 y 6 meses, luego cada 6 meses. Meta: carga viral indetectable. Screening de comorbilidades.",
            archivoGuiaSIGGES: "18_-_VIH_SIDA_v.6.0.pdf"
        ),
